in = new Scanner(System.in)
def list = []
N = in.nextInt()
for (i = 1; i <= N; ++i) {list.add(new Job(i, in.nextInt(), in.nextInt()))}
list.sort()
println list.join(' ')

class Job implements Comparable<Job> {
    int id, d, p
	int compareTo(Job o) {return Integer.compare(d * o.p, p * o.d)}    
	Job(int id, int d, int p) {this.id = id; this.d = d; this.p = p} 
    @Override String toString() {return "$id"}       
}
